const fs = require('node:fs');
const path = require('node:path');

const projectRoot = path.resolve(__dirname, '..');
const leafletRoot = path.dirname(require.resolve('leaflet/package.json'));
const vendorDirectory = path.join(projectRoot, 'src', 'vendor');
const javascript = fs.readFileSync(path.join(leafletRoot, 'dist', 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync(path.join(leafletRoot, 'dist', 'leaflet.css'), 'utf8').replace(/url\(images\/([^)]+)\)/g, (_, filename) => {
  const encodedImage = fs.readFileSync(path.join(leafletRoot, 'dist', 'images', filename)).toString('base64');
  return `url(data:image/png;base64,${encodedImage})`;
});

fs.mkdirSync(vendorDirectory, { recursive: true });
fs.writeFileSync(path.join(vendorDirectory, 'leaflet.ts'), `// Generated by scripts/bundleLeaflet.cjs. Leaflet 1.9.4, BSD-2-Clause.\n// Do not edit manually; the local bundle removes the runtime CDN dependency.\nexport const leafletJavascript = ${JSON.stringify(javascript)};\nexport const leafletCss = ${JSON.stringify(css)};\n`);
fs.copyFileSync(path.join(leafletRoot, 'LICENSE'), path.join(vendorDirectory, 'leafletLicense.txt'));
